/* DELGROSSO VIAGGI 2.0 — independent offline PDF generator, no CDN/service key.
 * Produces A4 PDF with pagination, operator ownership, method breakdown and receipts.
 * No personal data persisted: the PDF is built in the authenticated operator's browser.
 * This is an operational accounting summary, not an invoice/tax receipt.
 */
(function(root){'use strict';
const W=595.28,H=841.89;
const LOGO_JPEG_B64='';
const LOGO_WIDTH=760,LOGO_HEIGHT=397; // logo ufficiale DELGROSSO Viaggi - limousineBUS

const euro=x=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format((x||0)/100);
const date=x=>String(x||'').slice(0,10).replace(/^(\d{4})-(\d{2})-(\d{2})$/,'$3/$2/$1');
const text=x=>String(x??'').replace(/[\r\n\t]/g,' ').replace(/\s+/g,' ').trim();
function cp1252(s){const special={'€':128,'‚':130,'ƒ':131,'„':132,'…':133,'†':134,'‡':135,'ˆ':136,'‰':137,'Š':138,'‹':139,'Œ':140,'Ž':142,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'˜':152,'™':153,'š':154,'›':155,'œ':156,'ž':158,'Ÿ':159};const out=[];for(const c of text(s)){const code=c.codePointAt(0);out.push(code<=255?code:special[c]||63)}return out}
const hex=s=>cp1252(s).map(n=>n.toString(16).padStart(2,'0')).join('');
function pdfBytes(pages,title="Riepilogo gestionale"){
 // Object 5 contains PDF metadata, the final numbered object is the logo XObject.
 // Binary JPEG streams need byte-accurate offsets: never count them as JS string chars.
 const chunks=[];let offset=0;const loc=[0];
 const ascii=s=>Uint8Array.from(String(s),c=>c.charCodeAt(0)&255);
 const push=s=>{const b=typeof s==='string'?ascii(s):s;chunks.push(b);offset+=b.length};
 const obj=(id,body)=>{loc[id]=offset;push(id+' 0 obj\n'+body+'\nendobj\n')};
 push('%PDF-1.4\n%DELGROSSO\n');
 const contentsStart=6, logoObjId=contentsStart+pages.length*2;
 obj(1,'<< /Type /Catalog /Pages 2 0 R >>');
 obj(2,'<< /Type /Pages /Kids ['+pages.map((_,i)=>(contentsStart+i*2)+' 0 R').join(' ')+'] /Count '+pages.length+' >>');
 obj(3,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
 obj(4,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
 obj(5,'<< /Producer (DELGROSSO Gestionale 2.0) /Title ('+text(title).replace(/[()\\]/g,'').slice(0,60)+') >>');
 pages.forEach((p,i)=>{
  const pageId=contentsStart+i*2,contentId=pageId+1;
  const commands=p.join('\n')+'\n';
  obj(pageId,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+W+' '+H+'] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /ImLogo '+logoObjId+' 0 R >> >> /Contents '+contentId+' 0 R >>');
  obj(contentId,'<< /Length '+commands.length+' >>\nstream\n'+commands+'endstream');
 });
 const binaryLogo=typeof atob==='function'?Uint8Array.from(atob(LOGO_JPEG_B64),c=>c.charCodeAt(0)):new Uint8Array(Buffer.from(LOGO_JPEG_B64,'base64'));
 loc[logoObjId]=offset;
 push(logoObjId+' 0 obj\n<< /Type /XObject /Subtype /Image /Width '+LOGO_WIDTH+' /Height '+LOGO_HEIGHT+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+binaryLogo.length+' >>\nstream\n');
 push(binaryLogo);push('\nendstream\nendobj\n');
 const xref=offset,finalId=logoObjId+1;
 push('xref\n0 '+finalId+'\n0000000000 65535 f \n');
 for(let i=1;i<finalId;i++)push(String(loc[i]).padStart(10,'0')+' 00000 n \n');
 push('trailer\n<< /Size '+finalId+' /Root 1 0 R /Info 5 0 R >>\nstartxref\n'+xref+'\n%%EOF');
 const out=new Uint8Array(offset);let at=0;for(const piece of chunks){out.set(piece,at);at+=piece.length}
 return out;
}
class Sheet{
 constructor(kind='RIEPILOGO QUOTE'){this.kind=kind;this.pages=[];this.y=0;this.newPage()}
 add(code){this.pages[this.pages.length-1].push(code)}
 box(x,y,w,h,color){this.add(color.join(' ')+' rg '+x.toFixed(2)+' '+(H-y-h).toFixed(2)+' '+w.toFixed(2)+' '+h.toFixed(2)+' re f')}
 rule(x,y,w,color=[0.78,0.83,0.9]){this.add(color.join(' ')+' RG 0.5 w '+x+' '+(H-y).toFixed(2)+' m '+(x+w)+' '+(H-y).toFixed(2)+' l S')}
 label(txt,x,y,size=9,bold=false,color=[0.12,0.19,0.31]){this.add(color.join(' ')+' rg BT /F'+(bold?'2':'1')+' '+size+' Tf 1 0 0 1 '+x.toFixed(2)+' '+(H-y).toFixed(2)+' Tm <'+hex(txt)+'> Tj ET')}
 newPage(){this.pages.push([]);this.y=110;this.box(0,0,W,82,[1,1,1]);this.add('q 126.3 0 0 66 42 '+(H-8-66).toFixed(2)+' cm /ImLogo Do Q');this.label(this.kind,244,39,13,true,[0.07,0.16,0.31]);this.label(this.kind==='CONFERMA PRENOTAZIONE'?'RIEPILOGO PRENOTAZIONE - USO AZIENDALE':'VIAGGIO / PARTENZA - REPORT INTERNO',244,57,8,false,[0.35,0.45,0.59]);this.box(0,82,W,5,[0.07,0.16,0.31]);}
 ensure(space){if(this.y+space>H-67)this.newPage()}
 heading(txt){this.ensure(37);this.y+=8;this.box(42,this.y-14,W-84,27,[0.91,0.94,0.99]);this.label(txt,49,this.y+3,11,true);this.y+=30}
 paragraph(txt,style=''){const width=95;const words=text(txt).split(' ');let line='';for(const word of words){if((line+' '+word).length>width){this.ensure(16);this.label(line,43,this.y,8,style==='bold');this.y+=14;line=word}else line+=(line?' ':'')+word}if(line){this.ensure(16);this.label(line,43,this.y,8,style==='bold');this.y+=14}}
 stat(label,amount){this.ensure(23);this.label(label,45,this.y,9,false);this.label(euro(amount),455,this.y,10,true);this.y+=21}
 tableHead(){this.ensure(33);this.box(42,this.y-12,W-84,25,[0.86,0.9,0.97]);const x=[46,105,239,320,402,494];['Data','Partecipante','Tipo','Ric./Bus','Metodo','Importo'].forEach((s,i)=>this.label(s,x[i],this.y+3,8,true));this.y+=25}
 row(m,i){
  const name=text(m.cliente);const nameLines=name.match(/.{1,24}/g)||['Cliente non identificato'];
  const height=Math.max(24,18+11*(nameLines.length-1));this.ensure(height+1);
  if((i%2)===0)this.box(42,this.y-10,W-84,height,[0.967,0.978,0.993]);
  const x=[46,105,239,320,402,493];
  const cols=[date(m.date),nameLines[0],text(m.tipo).slice(0,14),(text(m.receipt)+' B'+text(m.bus)).slice(0,14),text(m.method||'Da verificare').slice(0,14),euro(m.amount)];
  cols.forEach((c,k)=>this.label(c,x[k],this.y+4,k===5?8:7.9,k===5));
  nameLines.slice(1).forEach((line,j)=>this.label(line,105,this.y+15+j*11,7.9));
  this.y+=height;
 }
 note(s){this.ensure(25);this.label(text(s).slice(0,98),46,this.y,8,false,[0.49,0.34,0.15]);this.y+=17}
 finish(){this.pages.forEach((p,i)=>{const foot=new SheetFooter(p);foot.write(i+1,this.pages.length)});return pdfBytes(this.pages,this.kind)}
}
class SheetFooter{constructor(p){this.p=p}write(n,total){const color=[0.39,0.47,0.59].join(' ');const t='Documento operativo interno - non sostituisce una ricevuta fiscale | Pagina '+n+' / '+total;this.p.push(color+' rg BT /F1 8 Tf 1 0 0 1 42 36 Tm <'+hex(t)+'> Tj ET')}}
function makeTripPdf(g){if(!g||!g.trip)throw Error('Seleziona un viaggio valido');const doc=new Sheet();
 doc.label('VIAGGIO: '+text(g.trip.titolo||g.trip.destinazione).slice(0,65),42,123,13,true);doc.y=144;
 doc.paragraph('Data: '+date(g.trip.data_partenza)+'  |  Autobus: '+g.buses.length+'  |  Codice: '+text(g.trip.id_viaggio||g.trip.id));
 doc.paragraph('Generato il: '+new Date().toLocaleString('it-IT')+'. Report degli incassi registrati. Le somme dei BUS BIS sono aggregate nella partenza principale.');
 const people=g.bookings.filter(b=>!/annull|cancel/i.test(String(b.stato||''))).reduce((sum,b)=>sum+(Number(b.posti)||0),0);
 doc.paragraph('Prenotazioni attive: '+g.bookings.filter(b=>!/annull|cancel/i.test(String(b.stato||''))).length+'  |  Persone prenotate: '+people);
 doc.heading('RIEPILOGO QUOTE PRENOTATE (NON SONO NUOVI INCASSI)');
 doc.stat('Valore complessivo delle prenotazioni attive',g.quote);
 doc.stat('Quote indicate come pagate nelle prenotazioni',g.saldatoDallePrenotazioni);
 doc.stat('Residuo complessivo delle prenotazioni attive',g.residuo);
 const owners=[['nicola','NICOLA'],['raffaele','RAFFAELE'],['nonAttribuiti','DA ATTRIBUIRE']];
 for(const [key,name] of owners){const part=g.owners[key],lines=g.movements.filter(m=>m.owner===key);
  doc.heading((key==='nonAttribuiti'?'VERSAMENTI DA ATTRIBUIRE':'INCASSI RICEVUTI DA '+name)+' ('+lines.length+' MOVIMENTI)');
  if(lines.length){doc.tableHead();lines.forEach((m,i)=>{if(doc.y>H-91)doc.tableHead();doc.row(m,i);if(m.issues?.length){for(const err of m.issues)doc.note('Da verificare: '+err)}})}else doc.paragraph('Nessun pagamento registrato per questo operatore.');
  doc.stat(name+' - contanti netti',part.contanti);
  doc.stat(name+' - POS / bonifici / altro',part.elettronici);
  doc.stat(name+' - metodo da verificare',part.daVerificare);
  doc.stat(name+' - totale incassi attribuiti',part.netto);
 }
 doc.heading('TOTALI INCASSATI SUL VIAGGIO');
 doc.stat('CONTANTI NETTI (Nicola + Raffaele + non attribuiti)',g.totals.contanti);
 doc.stat('PAGAMENTI NON CONTANTI (POS, bonifico, altro)',g.totals.elettronici);
 doc.stat('METODI DA VERIFICARE',g.totals.daVerificare);
 doc.stat('TOTALE MOVIMENTI REGISTRATI (rimborsi gia sottratti)',g.totals.netto);
 doc.paragraph('ATTENZIONE: i trasferimenti di contante da Nicola a Raffaele o viceversa non sono nuovi incassi. Il saldo fisico in mano agli operatori può differire dai totali qui mostrati.');
 if(g.issues.length){doc.heading('ANOMALIE DA CONTROLLARE');for(const m of [...new Set(g.issues)].slice(0,35))doc.paragraph('! '+m)}
 doc.paragraph('Fonte: pagamenti registrati nel gestionale Supabase al momento della generazione. Nessun movimento duplicato per ID. Importi in euro.');
 return doc.finish();
}
function saveTripPdf(g){const bytes=makeTripPdf(g),blob=new Blob([bytes],{type:'application/pdf'}),href=URL.createObjectURL(blob);const a=document.createElement('a');const safe=text(g.trip.titolo||'viaggio').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9_-]/g,'_').slice(0,42);a.download='DELGROSSO_QUOTE_'+date(g.trip.data_partenza).replaceAll('/','-')+'_'+safe+'.pdf';a.href=href;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),45000);return a.download}
function makeBookingPdf(b,t,movements=[]){
 if(!b?.id||!t?.id)throw Error('Prenotazione o viaggio mancanti');
 const doc=new Sheet('CONFERMA PRENOTAZIONE');doc.y=140;
 const cents=n=>Math.round((Number(n)||0)*100);
 const archived=false;
 doc.label('CONFERMA DI PRENOTAZIONE',42,126,14,true);
 doc.heading('DATI DELLA PRENOTAZIONE');
 doc.paragraph('Numero: '+text(b.confirmation_number||b.codice||b.id_prenotazione||b.id));
 doc.paragraph('Referente: '+text(b.cliente));
 doc.paragraph('Telefono: '+text(b.telefono||'non indicato')+'  |  Email: '+text(b.email||'non indicata'));
 doc.paragraph('Registrata il: '+(b.created_at?new Date(b.created_at).toLocaleString('it-IT',{timeZone:'Europe/Rome'}):new Date().toLocaleString('it-IT',{timeZone:'Europe/Rome'})));
 doc.heading('VIAGGIO E POSTI');
 doc.paragraph('Viaggio: '+text(t.titolo||t.destinazione));
 doc.paragraph('Data partenza: '+date(t.data_partenza)+'  |  Ora: '+text(t.ora_partenza||'da confermare'));
 doc.paragraph('Fermata: '+text(b.fermata_partenza||'da confermare'));
 doc.paragraph('Autobus: '+text(t.autobus||'Autobus GT')+'  |  Passeggeri: '+Number(b.posti||0));
 doc.paragraph('Posti assegnati: '+text(b.posti_selezionati||'non assegnati'));
 doc.paragraph('Stato della prenotazione: '+text(b.stato||'da confermare'));
 doc.heading('SITUAZIONE ECONOMICA');
 doc.stat('Totale prenotazione',cents(b.totale));
 doc.stat('Versato risultante dall’archivio',cents(b.pagato));
 doc.stat('Residuo',cents(Math.max(0,Number(b.totale||0)-Number(b.pagato||0))));
 if(movements.length){doc.paragraph('Movimenti registrati: '+movements.length+' (verificare la sezione Pagamenti).');}
 doc.heading('CONDIZIONI E AVVERTENZE');
 doc.paragraph('Gli acconti seguono le condizioni della prenotazione. In caso di rinuncia del cliente si applicano le condizioni comunicate; se il viaggio non raggiunge il minimo previsto, verificare le condizioni di rimborso.');
 doc.paragraph('Questa è una conferma di prenotazione e un riepilogo operativo; non sostituisce ricevuta fiscale o fattura. Le modifiche successive possono rendere superata questa versione del documento.');
 doc.paragraph('Generato il '+new Date().toLocaleString('it-IT',{timeZone:'Europe/Rome'})+' · DELGROSSO VIAGGI & LIMOUSINE BUS');
 return doc.finish();
}
function saveBookingPdf(b,t,movements=[]){
 const bytes=makeBookingPdf(b,t,movements),blob=new Blob([bytes],{type:'application/pdf'}),href=URL.createObjectURL(blob);
 const a=document.createElement('a');a.href=href;a.download='DELGROSSO_CONFERMA_'+text(b.confirmation_number||b.codice||b.id).replace(/[^a-zA-Z0-9_-]/g,'_')+'.pdf';
 document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),5000);return a.download;
}
function makeOperatorPdf(profile,onlyTrip=''){
 if(!profile||!['nicola','raffaele'].includes(profile.key))throw Error('Seleziona contabilità Nicola o Raffaele');
 // DG34: un PDF di singolo viaggio deve avere TOTALI E RIGHE limitati a quel viaggio.
 // Non mostrare il totale generale insieme all'etichetta di una partenza.
 if(onlyTrip){
  const filtered=(profile.trips||[]).filter(g=>String(g.id)===String(onlyTrip));
  const signed=x=>filtered.reduce((sum,g)=>sum+(Number(g[x])||0),0);
  profile={...profile,trips:filtered,net:signed('net'),cash:signed('cash'),
   electronic:signed('electronic'),unknown:signed('unknown'),transferredIn:0,transferredOut:0,
   inHand:signed('cash'),rentals:null};
 }
 const doc=new Sheet('CONTABILITA '+profile.name.toUpperCase());doc.y=139;
 doc.label('CONTABILITA DI '+profile.name.toUpperCase(),42,123,13,true);
 doc.paragraph('DELGROSSO VIAGGI & LIMOUSINE BUS | Documento gestionale interno');
 doc.paragraph('Data generazione: '+new Date().toLocaleString('it-IT',{timeZone:'Europe/Rome'})+' · '+(onlyTrip?'Viaggio: '+onlyTrip:'Tutti i viaggi'));
 doc.heading('RIEPILOGO MOVIMENTI REGISTRATI');
 doc.stat('TOTALE INCASSI NETTI ATTRIBUITI',profile.net);
 doc.stat('Contanti incassati (rimborsi detratti)',profile.cash);
 doc.stat('POS, bonifici e pagamenti elettronici',profile.electronic);
 doc.stat('Metodi da verificare',profile.unknown);
 if(!onlyTrip){
 doc.stat('Trasferimenti contanti ricevuti',profile.transferredIn);
 doc.stat('Trasferimenti contanti consegnati',profile.transferredOut);
 doc.stat('Contanti in carico dopo trasferimenti',profile.inHand);
 }
 doc.heading('DETTAGLIO PER VIAGGIO');
 for(const g of profile.trips||[]){
  doc.heading(String(g.trip.titolo||g.trip.destinazione||'Viaggio').slice(0,65)+' · '+date(g.trip.data_partenza));
  doc.stat('Totale netto '+profile.name+' per questo viaggio',g.net);
  doc.stat('Contanti',g.cash);doc.stat('POS e bonifici',g.electronic);
  doc.stat('Metodi da verificare',g.unknown);
  if(g.movements.length){doc.tableHead();for(let i=0;i<g.movements.length;i++){
    const m=g.movements[i];doc.row({date:m.date,cliente:m.client,tipo:m.refund?'Rimborso':'Incasso',receipt:m.receipt,bus:m.bus,method:m.method,amount:m.amount},i);
  }}
 }
 if(!onlyTrip&&profile.rentals){
  const rental=profile.rentals;
  doc.heading('REGISTRO SEPARATO NOLEGGI AUTOBUS');
  doc.stat('Incassi noleggi netti registrati',rental.net);
  doc.stat('Contanti noleggi',rental.cash);
  doc.stat('Elettronici noleggi',rental.electronic);
  doc.stat('TOTALE GITE E NOLEGGI (senza duplicare Economia)',profile.net+rental.net);
  if(rental.items?.length){doc.tableHead();rental.items.forEach((m,i)=>doc.row({
    date:m.date,cliente:m.rental,tipo:m.kind,receipt:m.receipt,bus:'N',method:m.method,amount:m.amount},i));}
 }
 doc.heading('NOTA CONTABILE');
 doc.paragraph('Tutti gli importi sono riportati dai movimenti registrati su Supabase. POS e bonifici non sono contanti disponibili fisicamente. I rimborsi sono sottratti. I trasferimenti non costituiscono nuovi incassi.');
 doc.paragraph('Le somme possono differire dal denaro fisicamente disponibile se ci sono spese, prelievi o trasferimenti non registrati.');
 return doc.finish();
}
function saveOperatorPdf(profile,onlyTrip=''){
 const bytes=makeOperatorPdf(profile,onlyTrip),blob=new Blob([bytes],{type:'application/pdf'}),href=URL.createObjectURL(blob),a=document.createElement('a');
 const t=String(onlyTrip||'TUTTI_I_VIAGGI').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9_-]/g,'_').slice(0,60);
 a.download='DELGROSSO_CONTABILITA_'+profile.name.toUpperCase()+'_'+t+'.pdf';a.href=href;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),30000);return a.download;
}
function makeLayoutPdf(layout){
 if(!layout||!Array.isArray(layout.rows)||!layout.rows.length)throw Error('Piantina non valida');
 const rows=layout.rows;
 const all=rows.flat().filter(x=>Number.isInteger(x)&&x>0);
 if(!all.length||new Set(all).size!==all.length)throw Error('Servono posti numerati senza duplicati');
 if(rows.some(row=>!Array.isArray(row)||row.length!==5))throw Error('Le file devono avere cinque celle');
 const doc=new Sheet('PIANTINA POSTI A SEDERE');doc.y=132;
 doc.label('DELGROSSO - '+text(layout.name||'Autobus GT').slice(0,48),43,122,12,true);
 doc.y=149;
 doc.paragraph('Posti numerati: '+all.length+' | File: '+rows.length+' | Documento operativo da piantina personalizzata');
 doc.paragraph('Schema: sedili azzurri, corridoio bianco, porta color sabbia. Il PDF riproduce la numerazione del modello salvato.');
 doc.heading(text(layout.frontLabel||'FRONTE AUTOBUS').slice(0,65)+' - '+text(layout.driverLabel||'AUTISTA'));
 const left=102,w=67,gap=5,step=31;
 rows.forEach((row,i)=>{
  doc.ensure(step+7);
  const y=doc.y;
  doc.label('Fila '+String(i+1).padStart(2,'0'),45,y+17,8,false,[.35,.43,.54]);
  row.forEach((cell,c)=>{
   const x=left+c*(w+gap),seat=Number.isInteger(cell)&&cell>0;
   const tint=seat?[.83,.91,.99]:cell==='door'?[.98,.87,.68]:cell==='aisle'?[.96,.97,.98]:[.98,.98,.98];
   doc.box(x,y,w,26,tint);
   if(seat)doc.label(String(cell),x+23,y+17,12,true,[.05,.31,.54]);
   else if(cell==='door')doc.label('PORTA',x+12,y+16,7,true,[.42,.30,.14]);
   else if(cell==='aisle')doc.label('CORR.',x+16,y+16,7,false,[.55,.60,.66]);
  });
  doc.y+=step;
 });
 doc.y+=12;doc.paragraph('Documento generato il '+new Date().toLocaleString('it-IT',{timeZone:'Europe/Rome'})+' - DELGROSSO VIAGGI & LIMOUSINE BUS');
 return doc.finish();
}
function saveLayoutPdf(layout){
 const bytes=makeLayoutPdf(layout),blob=new Blob([bytes],{type:'application/pdf'}),url=URL.createObjectURL(blob);
 const name=text(layout.name||'PIANTINA').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9_-]/g,'_').slice(0,60);
 const file='DELGROSSO_PIANTINA_'+name+'.pdf',a=document.createElement('a');a.download=file;a.href=url;
 document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);return file;
}

// V9: elenchi nominativi per singola partenza e per tutti i viaggi, inclusi i BUS BIS.
// Riceve esclusivamente dati autenticati già caricati; nessun upload o URL pubblico.
function makeRosterPdf(groups,settings={}){
 if(!Array.isArray(groups)||!groups.length)throw Error('Nessun viaggio da esportare');
 const doc=new Sheet('LISTA PRENOTATI');doc.y=122;
 const only=groups.length===1;
 doc.label(only?'ELENCO PRENOTATI - VIAGGIO':'ELENCO PRENOTATI - TUTTI I VIAGGI',43,125,12,true);
 doc.y=147;
 doc.paragraph('Generato: '+new Date().toLocaleString('it-IT',{timeZone:'Europe/Rome'})+' | '+(settings.includeArchived?'Anche viaggi archiviati':'Viaggi operativi'));
 doc.paragraph('Elenco interno riservato agli operatori autorizzati. Sono riportati i referenti registrati per ogni prenotazione, non i nomi di passeggeri non presenti in archivio.');
 let totalBookings=0,totalPax=0,totalBus=0;
 for(const group of groups){
  const rows=(group.buses||[]).flatMap(bus=>bus.bookings||[]),pax=rows.reduce((a,b)=>a+Math.max(0,Number(b.posti)||0),0);
  totalBookings+=rows.length;totalPax+=pax;totalBus+=(group.buses||[]).length;
  doc.ensure(77);
  doc.heading(String(group.trip?.titolo||group.trip?.destinazione||'Viaggio').slice(0,68));
  doc.paragraph('DATA: '+date(group.trip?.data_partenza)+' | Prenotazioni: '+rows.length+' | Persone: '+pax+(group.trip?.archiviato_at?' | ARCHIVIATO':''));
  for(const bus of group.buses||[]){
   doc.ensure(63);
   const list=bus.bookings||[],sum=list.reduce((a,b)=>a+Math.max(0,Number(b.posti)||0),0);
   doc.box(42,doc.y-9,W-84,25,[.90,.94,.98]);
   doc.label(String(bus.name||'BUS 1').slice(0,60)+'  -  '+list.length+' prenotazioni / '+sum+' passeggeri',48,doc.y+7,9,true);
   doc.y+=28;
   if(!list.length){doc.paragraph('Nessuna prenotazione attiva.');continue}
   const head=()=>{
    doc.ensure(34);doc.box(42,doc.y-10,W-84,25,[.87,.90,.95]);
    [['#',47],['Cliente / codice',72],['Telefono',225],['Pax',314],['Posti',345],['Fermata',416]].forEach(([v,x])=>doc.label(v,x,doc.y+6,8,true));doc.y+=25;
   };
   head();
   list.forEach((b,i)=>{
    // Fixed column widths; long values are split over up to two lines.
    const chunks=(v,max)=>{
      const txt=text(v||'-');if(txt.length<=max)return [txt];
      let start=txt.slice(0,max),cut=start.lastIndexOf(' ');
      if(cut>Math.floor(max*.54))start=txt.slice(0,cut);
      const rest=txt.slice(start.length).trim();return [start,rest.length>max?rest.slice(0,max-1)+'…':rest];
    };
    const customer=chunks(b.cliente_nome||b.cliente||'Nominativo non registrato',28);
    const seats=chunks(b.posti_selezionati||'Da assegnare',12);
    const stop=chunks(b.fermata_partenza||'Non indicata',25);
    const phone=chunks(b.telefono||'Non inserito',16);
    // Include booking code under the name only when space allows, or as the second line.
    const code=String(b.codice||b.id_prenotazione||'').trim();
    const lines=Math.max(customer.length,phone.length,seats.length,stop.length,code?2:1);
    const h=Math.max(29,13+11*lines);
    if(doc.y+h>H-70){doc.newPage();head()}
    if(i%2===0)doc.box(42,doc.y-9,W-84,h,[.967,.977,.99]);
    doc.label(String(i+1),47,doc.y+7,8);
    doc.label(customer[0],72,doc.y+7,7.6,true);
    if(customer.length>1)doc.label(customer[1],72,doc.y+18,7.2);
    else if(code)doc.label('Rif. '+code.slice(0,24),72,doc.y+18,7.0,false,[.40,.47,.55]);
    doc.label(phone[0],225,doc.y+7,7.9);
    if(phone.length>1)doc.label(phone[1],225,doc.y+18,7.1);
    doc.label(String(Math.max(0,Number(b.posti)||0)),317,doc.y+7,8,true);
    doc.label(seats[0],345,doc.y+7,7.3);
    if(seats.length>1)doc.label(seats[1],345,doc.y+18,7.1);
    doc.label(stop[0],416,doc.y+7,7.7);
    if(stop.length>1)doc.label(stop[1],416,doc.y+18,7.0);
    doc.y+=h;
   });
  }
  doc.ensure(32);doc.y+=5;doc.rule(42,doc.y,W-84);doc.y+=15;
 }
 doc.heading('TOTALI DEL REPORT');
 doc.paragraph('Viaggi: '+groups.length+' | Autobus: '+totalBus+' | Prenotazioni: '+totalBookings+' | Persone prenotate: '+totalPax,'bold');
 doc.paragraph('Prenotazioni annullate e riserve aziendali escluse. Il numero dei referenti non coincide necessariamente con il numero dei passeggeri.');
 return doc.finish();
}

/** DG33: report nominale di bordo con piantina ufficiale (quando disponibile),
 * fermate per paese, BUS/BIS e riscontri sulle assegnazioni. Nessuna scrittura. */
function makeOperationalPdf(groups,opts={}){
 if(!Array.isArray(groups)||!groups.length)throw Error('Nessuna partenza da esportare');
 const resolver=root.DGSeatGroups;
 if(!resolver?.buildPlan)throw Error('Modulo colori e geometrie piantine non caricato. Aggiorna il gestionale.');
 const doc=new Sheet(opts.onlyMaps?'PIANTINA PASSEGGERI - GRUPPI':'CONTROL ROOM - LISTE E PIANTINE');
 doc.y=115;
 doc.paragraph('DELGROSSO VIAGGI & LIMOUSINE BUS | '+new Date().toLocaleString('it-IT',{timeZone:'Europe/Rome'}));
 doc.paragraph('Un colore e un codice G per ciascuna prenotazione. Le persone nella stessa prenotazione condividono lo stesso colore.');
 doc.paragraph('I nominativi sono i REFERENTI della prenotazione, non i nomi dei singoli passeggeri. Documento aziendale riservato.');
 const slim=(v,n)=>text(String(v??'').trim()||'-').slice(0,n);
 let totalPeople=0,totalBookings=0;
 let groupByBooking=new Map();
 function lineHeader(){
  doc.ensure(28);doc.box(42,doc.y-10,W-84,23,[.86,.91,.97]);
  [['Posti',47],['Gruppo / referente',105],['Pers.',290],['Fermata di salita',330],['Check-in',486]]
   .forEach(([name,x])=>doc.label(name,x,doc.y+6,7.6,true));doc.y+=25;
 }
 function listRow(b,i){
  const h=27;if(doc.y+h>H-64){doc.newPage();lineHeader()}
  if(i%2===0)doc.box(42,doc.y-9,W-84,h,[.965,.973,.99]);
  const seats=(Array.isArray(b.sedili)?b.sedili:[]).join(', ')||'-';
  const g=groupByBooking.get(String(b.id||b.codice));
  doc.label(slim(seats,12),47,doc.y+7,7.6,true);
  if(g){doc.box(104,doc.y-6,28,18,g.pdf);doc.label(g.number,107,doc.y+7,8,true);}
  doc.label(slim(b.cliente_nome||b.cliente||'Nominativo assente',28),g?137:105,doc.y+7,7.5);
  doc.label(String(Math.max(0,Number(b.posti)||0)),293,doc.y+7,8,true);
  doc.label(slim(b.fermata_partenza||'NON INDICATA',24),330,doc.y+7,7.4);
  doc.label(b.checkin_effettuato?'SI':'-',489,doc.y+7,7.4);
  doc.y+=h;
 }
 for(const group of groups){
  doc.ensure(84);doc.heading(slim(group.title||group.trip?.titolo||'PARTENZA',70));
  doc.paragraph('Data: '+slim(group.trip?.data_partenza,20)+' - Autobus: '+(group.buses||[]).length);
  for(const bus of group.buses||[]){
   const list=bus.bookings||[],people=list.reduce((a,b)=>a+Math.max(0,Number(b.posti)||0),0);
   totalPeople+=people;totalBookings+=list.length;
   doc.ensure(67);doc.heading(slim(bus.name||bus.trip?.titolo||'AUTOBUS',62));
   doc.paragraph('Prenotazioni: '+list.length+' | Passeggeri: '+people+' | Capienza viaggio: '+(bus.trip?.posti_totali??'-'));
   let plan=null;
   if(bus.layout?.rows?.length && bus.official){
    // Never fabricate or renumber a seat: identical layout snapshot used on the booking site.
    plan=resolver.buildPlan({layout:bus.layout,bookings:list,seatRows:bus.seatRows||[],
      capacity:bus.trip?.posti_totali,strict:true});
    if(plan.warnings.length){
     doc.heading('ATTENZIONE - ASSEGNAZIONI DA RICONCILIARE');
     for(const warning of plan.warnings.slice(0,14))doc.note(slim(warning,108));
    }
    const source=bus.layoutSource==='autobus'?'AUTOBUS':bus.layoutSource==='viaggio'?'VIAGGIO':'PUBBLICATA';
    // Ogni piantina apre un foglio dedicato: mai spezzare la geometria 53/57/63 posti.
    doc.newPage();
    doc.label('PIANTINA UFFICIALE - '+source+' - VERSIONE '+(bus.layoutVersion||'?'),43,doc.y+4,8,true,[.08,.43,.33]);doc.y+=22;
    doc.label('FRONTE AUTOBUS  |  AUTISTA',44,doc.y+6,9,true);doc.y+=22;
    groupByBooking=new Map(plan.groups.map(g=>[g.id,g]));
    const cols=plan.geometry.columns;
    const rowCount=plan.geometry.rows.length;
    const rowStep=Math.min(36,(H-doc.y-70)/rowCount);
    const cellH=rowStep-3;
    for(const [rowIndex,row] of plan.geometry.rows.entries()){
     if(doc.y+rowStep>H-66){doc.newPage();doc.label('PIANTINA - SEGUE | FRONTE AUTOBUS SOPRA',43,doc.y+9,8,true);doc.y+=28;}
     const y=doc.y-8;
     const rowCols=row.cells.length,pitch=(W-84)/rowCols,boxWidth=pitch-3;
     const labelMax=rowCols<=5?18:rowCols<=7?11:8;
     row.cells.forEach((cell,column)=>{
      const x=42+column*pitch,seat=cell.type==='seat'?cell.id:null;
      const occ=seat?plan.bySeat.get(seat):null;
      const tint=occ?occ.pdf:cell.type==='seat'&&cell.status!=='available'?[.98,.87,.82]:
       cell.type==='seat'?[.87,.95,.90]:cell.type==='door'?[.99,.89,.73]:[.95,.96,.98];
      doc.box(x,y,boxWidth,cellH,tint);
      if(seat){
       const compact=cellH<28;
       doc.label('POSTO '+slim(seat,3),x+3,y+(compact?10:11),rowCols>=7?6.5:7.8,true,[.09,.19,.30]);
       if(occ){
        doc.label(occ.number,x+3,y+(compact?22:21),rowCols>=7?7:8.8,true,[.06,.15,.24]);
        if(!compact)doc.label(slim(occ.name,labelMax),x+3,y+31,rowCols>=7?5.3:6.4,false,[.07,.14,.20]);
       }else doc.label(cell.status==='available'?'LIBERO':'BLOCCATO',x+3,y+(compact?22:25),rowCols>=7?5.6:7);
      }else{
       const labels={aisle:'CORRIDOIO',door:'PORTA',wc:'WC',table:'TAVOLO',driver:'AUTISTA',empty:''};
       if(labels[cell.type])doc.label(slim(labels[cell.type],rowCols>=7?7:10),x+3,y+22,rowCols>=7?5.5:7.4,true);
      }
     });
     doc.y+=rowStep;
    }
    doc.y+=10;
    doc.heading('LEGENDA COLORI E POSTI - '+plan.groups.length+' GRUPPI');
    if(!plan.groups.length)doc.paragraph('Nessuna prenotazione attiva con sedili assegnati.');
    for(const [i,g] of plan.groups.entries()){
     doc.ensure(24);
     if(i%2===0)doc.box(42,doc.y-8,W-84,23,[.97,.98,.99]);
     doc.box(47,doc.y-5,25,17,g.pdf);
     doc.label(g.number,49,doc.y+7,8,true);
     doc.label(slim(g.name,31),79,doc.y+7,8,true);
     doc.label(slim('POSTI '+(g.seats.join(', ')||'DA ASSEGNARE'),38),294,doc.y+7,7.4);
     doc.y+=24;
    }
    doc.y+=9;
   }else{
    if(opts.requireOfficial)throw Error('Piantina ufficiale non pubblicata per '+(bus.name||'BUS')+'. Associa e pubblica la stessa piantina del sito prima di stampare.');
    doc.ensure(50);doc.box(42,doc.y-8,W-84,38,[.99,.90,.84]);
    doc.label('PIANTINA UFFICIALE NON DISPONIBILE',47,doc.y+7,9,true,[.55,.23,.08]);
    doc.y+=24;
    doc.paragraph('Schema non stampato per evitare una disposizione diversa da quella del sito.');
   }
   if((bus.warnings||[]).length){doc.heading('VERIFICHE PRIMA DELLA PARTENZA');for(const w of bus.warnings.slice(0,12))doc.note(slim(w,105));}
   if(!opts.onlyMaps){
    doc.heading('ELENCO POSTI ASSEGNATI');
    lineHeader();list.slice().sort((a,b)=>Number((a.sedili||[])[0]||999)-Number((b.sedili||[])[0]||999)).forEach(listRow);
    doc.heading('SALITA PASSEGGERI - PER FERMATA');
    const stops=new Map();for(const b of list){const stop=String(b.fermata_partenza||'FERMATA NON INDICATA').trim()||'FERMATA NON INDICATA';if(!stops.has(stop))stops.set(stop,[]);stops.get(stop).push(b)}
    for(const [stop,selected] of [...stops.entries()].sort((a,b)=>a[0].localeCompare(b[0],'it'))){
     const count=selected.reduce((n,b)=>n+Math.max(0,Number(b.posti)||0),0);
     doc.ensure(52);doc.box(42,doc.y-8,W-84,24,[.90,.94,.98]);
     doc.label(slim(stop,48)+' | '+selected.length+' prenotazioni / '+count+' persone',47,doc.y+8,8.2,true);doc.y+=28;
     lineHeader();selected.forEach(listRow);
    }
   }
   if(!list.length)doc.paragraph('Nessun passeggero registrato su questo autobus.');
   doc.ensure(25);doc.paragraph('Totale BUS: '+people+' persone | '+list.length+' prenotazioni','bold');
  }
 }
 doc.heading('TOTALI');doc.paragraph('Partenze: '+groups.length+' | Prenotazioni: '+totalBookings+' | Passeggeri: '+totalPeople,'bold');
 doc.paragraph('Documento operativo riservato, generato dai dati autenticati. Non modifica prenotazioni né pagamenti.');
 return doc.finish();
}

root.DG2Pdf={makeTripPdf,saveTripPdf,makeBookingPdf,saveBookingPdf,makeOperatorPdf,saveOperatorPdf,makeLayoutPdf,saveLayoutPdf,makeRosterPdf,makeOperationalPdf};if(typeof module!=='undefined'&&module.exports)module.exports=root.DG2Pdf;
})(typeof window!=='undefined'?window:globalThis);
